from pathlib import Path

x = Path('camera-auto-upload-windows/MainWindow.xaml')
s = x.read_text(encoding='utf-8')

s = s.replace('Title="Camera Auto Upload" Width="1280" Height="920" MinWidth="980" MinHeight="700"\n        Background="#05080C" Foreground="#F5F7FA" WindowStartupLocation="CenterScreen" ShowInTaskbar="True">',
'''Title="Camera Auto Upload for Windows — v1.0.5" Width="1440" Height="900" MinWidth="1100" MinHeight="720"\n        Background="#0B0D10" Foreground="#F5F7FA" WindowStartupLocation="CenterScreen" ShowInTaskbar="True" WindowState="Maximized">''')

# Desktop-scale Windows styling instead of the phone-style rounded UI.
s = s.replace('CornerRadius="12" Padding="{TemplateBinding Padding}"', 'CornerRadius="6" Padding="{TemplateBinding Padding}"')
s = s.replace('<Setter Property="CornerRadius" Value="18"/>', '<Setter Property="CornerRadius" Value="9"/>')
s = s.replace('<Setter Property="Height" Value="66"/><Setter Property="FontSize" Value="12"/><Setter Property="Padding" Value="4"/><Setter Property="Margin" Value="2"/>',
              '<Setter Property="Height" Value="42"/><Setter Property="MinWidth" Value="108"/><Setter Property="FontSize" Value="13"/><Setter Property="Padding" Value="12,5"/><Setter Property="Margin" Value="3,0"/>')
s = s.replace('<Setter Property="MinWidth" Value="96"/><Setter Property="Height" Value="54"/><Setter Property="FontSize" Value="12"/><Setter Property="FontWeight" Value="Bold"/><Setter Property="Padding" Value="8,4"/>',
              '<Setter Property="MinWidth" Value="84"/><Setter Property="Height" Value="42"/><Setter Property="FontSize" Value="12"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Padding" Value="10,4"/>')
s = s.replace('<Setter Property="MinWidth" Value="88"/><Setter Property="Height" Value="48"/><Setter Property="FontSize" Value="11"/><Setter Property="Background" Value="#18212B"/><Setter Property="Padding" Value="8,3"/>',
              '<Setter Property="MinWidth" Value="82"/><Setter Property="Height" Value="38"/><Setter Property="FontSize" Value="11"/><Setter Property="Background" Value="#18212B"/><Setter Property="Padding" Value="9,3"/>')

# Taller desktop title strip, content, compact Windows navigation/status strip.
s = s.replace('<Grid.RowDefinitions><RowDefinition Height="62"/><RowDefinition Height="*"/><RowDefinition Height="76"/></Grid.RowDefinitions>',
              '<Grid.RowDefinitions><RowDefinition Height="72"/><RowDefinition Height="*"/><RowDefinition Height="56"/></Grid.RowDefinitions>')

start = s.index('        <!-- Android-style top app bar -->')
end = s.index('        <Grid Grid.Row="1">', start)
header = '''        <!-- Windows desktop title / command header -->\n        <Border Grid.Row="0" Background="#111419" BorderBrush="#242A31" BorderThickness="0,0,0,1" Margin="-12,-8,-12,0">\n            <Grid Margin="18,0">\n                <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>\n                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">\n                    <Border Width="44" Height="44" Background="#1C222A" BorderBrush="#343D47" BorderThickness="1" CornerRadius="8"><TextBlock Text="📷" FontSize="23" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border>\n                    <StackPanel Margin="12,0,0,0" VerticalAlignment="Center">\n                        <TextBlock x:Name="PageTitle" Text="Camera Auto Upload" FontSize="23" FontWeight="SemiBold"/>\n                        <TextBlock Text="Windows camera transfer + editor workflow" Foreground="#8F9AA6" FontSize="11"/>\n                    </StackPanel>\n                </StackPanel>\n                <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">\n                    <Border Background="#171C22" BorderBrush="#303842" BorderThickness="1" CornerRadius="6" Padding="12,6" Margin="0,0,8,0">\n                        <TextBlock x:Name="VersionText" Text="WINDOWS v1.0.5" Foreground="#C9D3DD" FontSize="12" FontWeight="SemiBold"/>\n                    </Border>\n                    <Button Content="Settings" Click="Settings_Click" MinWidth="92" Height="36" Background="#1B222A"/>\n                </StackPanel>\n            </Grid>\n        </Border>\n\n'''
s = s[:start] + header + s[end:]

# Replace phone-width Home with full-width Windows dashboard.
hs = s.index('            <!-- HOME:')
he = s.index('            <!-- PHOTOS:', hs)
home = '''            <!-- HOME: Windows desktop dashboard -->\n            <Grid x:Name="HomePage" Visibility="Visible" Margin="6,10,6,6">\n                <Grid.ColumnDefinitions><ColumnDefinition Width="1.55*"/><ColumnDefinition Width="1*"/><ColumnDefinition Width="1*"/></Grid.ColumnDefinitions>\n                <Grid.RowDefinitions><RowDefinition Height="*"/></Grid.RowDefinitions>\n\n                <Border Grid.Column="0" Style="{StaticResource Card}" Padding="18" Margin="4">\n                    <Grid>\n                        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>\n                        <StackPanel Orientation="Horizontal">\n                            <StackPanel>\n                                <TextBlock Text="Selected camera" FontSize="13" Foreground="{StaticResource Muted}"/>\n                                <TextBlock x:Name="HomeCameraName" Text="Nikon Z8" FontSize="28" FontWeight="SemiBold" Margin="0,2,0,0"/>\n                            </StackPanel>\n                            <Border HorizontalAlignment="Right" Margin="18,2,0,0" Background="#17351F" BorderBrush="#2D7D43" BorderThickness="1" CornerRadius="6" Padding="10,5">\n                                <TextBlock x:Name="HomeCameraStatus" Text="Waiting for camera" Foreground="#72DE91" FontWeight="SemiBold"/>\n                            </Border>\n                        </StackPanel>\n                        <Border Grid.Row="1" Background="#080A0D" BorderBrush="#2A3038" BorderThickness="1" CornerRadius="8" Margin="0,14,0,12" MinHeight="360">\n                            <Viewbox Stretch="Uniform"><Canvas x:Name="HomeCameraArt" Width="560" Height="330"/></Viewbox>\n                        </Border>\n                        <TextBlock Grid.Row="2" x:Name="HomeCameraMode" Text="Direct Wi-Fi FTP" FontSize="15" Foreground="#AAB6C2"/>\n                        <WrapPanel Grid.Row="3" Margin="0,10,0,0">\n                            <Button Content="Choose camera" Background="#1A73E8" Click="ChooseCamera_Click" MinWidth="132"/>\n                            <Button Content="Camera setup" Background="#237A3B" Click="CameraSetup_Click" MinWidth="132"/>\n                            <Button Content="USB / Tether" Click="UsbTether_Click" MinWidth="120"/>\n                        </WrapPanel>\n                        <TextBlock Grid.Row="4" Text="Pick a model and the camera artwork above changes to match the selected camera family and model." Foreground="#7F8A95" FontSize="11" Margin="4,8,0,0" TextWrapping="Wrap"/>\n                    </Grid>\n                </Border>\n\n                <StackPanel Grid.Column="1" Margin="4">\n                    <Border Style="{StaticResource Card}" Padding="16">\n                        <StackPanel>\n                            <TextBlock Text="Connection" FontSize="18" FontWeight="SemiBold"/>\n                            <TextBlock x:Name="ConnectionSummary" Text="Waiting for camera" Foreground="#C7D0D8" TextWrapping="Wrap" Margin="0,9,0,10" LineHeight="20"/>\n                            <UniformGrid Columns="1">\n                                <Button Content="Wi-Fi / FTP setup" Background="#1A73E8" Click="CameraSetup_Click"/>\n                                <Button Content="Windows hotspot" Background="#6048A8" Click="Hotspot_Click"/>\n                                <Button Content="Advanced camera / FTP" Click="AdvancedCamera_Click"/>\n                            </UniformGrid>\n                        </StackPanel>\n                    </Border>\n                    <Border Style="{StaticResource Card}" Padding="16">\n                        <StackPanel>\n                            <TextBlock Text="Editor automation" FontSize="18" FontWeight="SemiBold"/>\n                            <TextBlock x:Name="EditorAutomationText" Text="Open Editor, build the layout, then LOCK it for incoming camera photos." Foreground="{StaticResource Muted}" TextWrapping="Wrap" Margin="0,8,0,10" LineHeight="20"/>\n                            <Button Content="Open photo editor" Background="#1A73E8" Click="Editor_Click"/>\n                            <Border Background="#171D23" CornerRadius="6" Padding="10" Margin="4,8,4,0"><TextBlock x:Name="HomeLockStatus" Text="Layout unlocked" Foreground="#F4C64B" FontWeight="SemiBold"/></Border>\n                        </StackPanel>\n                    </Border>\n                </StackPanel>\n\n                <StackPanel Grid.Column="2" Margin="4">\n                    <Border Style="{StaticResource Card}" Padding="16">\n                        <StackPanel>\n                            <TextBlock Text="Flickr queue" FontSize="18" FontWeight="SemiBold"/>\n                            <TextBlock x:Name="HomeQueueStatus" Text="0 pending" FontSize="28" FontWeight="SemiBold" Foreground="#68D687" Margin="0,6,0,2"/>\n                            <Button Content="Open uploads" Click="Uploads_Click" HorizontalAlignment="Left"/>\n                        </StackPanel>\n                    </Border>\n                    <Border Style="{StaticResource Card}" Padding="16">\n                        <StackPanel>\n                            <TextBlock Text="Activity" FontSize="18" FontWeight="SemiBold"/>\n                            <TextBox x:Name="ActivityLog" Height="290" IsReadOnly="True" AcceptsReturn="True" VerticalScrollBarVisibility="Auto" TextWrapping="Wrap" Margin="0,8,0,0"/>\n                        </StackPanel>\n                    </Border>\n                </StackPanel>\n            </Grid>\n\n'''
s = s[:hs] + home + s[he:]

# Windows-style command navigation instead of phone bottom tabs.
ns = s.index('        <!-- Android-style bottom nav -->')
ne = s.rindex('    </Grid>\n</Window>')
nav = '''        <!-- Windows desktop command/navigation bar -->\n        <Border Grid.Row="2" Background="#111419" BorderBrush="#242A31" BorderThickness="0,1,0,0" Margin="-12,0,-12,-10">\n            <Grid Margin="16,7">\n                <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>\n                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">\n                    <Button Style="{StaticResource NavButton}" Content="Home" Click="Home_Click"/>\n                    <Button Style="{StaticResource NavButton}" Content="Photos" Click="Photos_Click"/>\n                    <Button Style="{StaticResource NavButton}" Content="Uploads" Click="Uploads_Click"/>\n                    <Button Style="{StaticResource NavButton}" Content="Settings" Click="Settings_Click"/>\n                    <Button Style="{StaticResource NavButton}" Content="Photo Editor" Click="Editor_Click" Background="#172536"/>\n                </StackPanel>\n                <TextBlock Grid.Column="1" Text="Camera Auto Upload for Windows  •  v1.0.5" Foreground="#7F8A95" VerticalAlignment="Center" Margin="12,0,0,0"/>\n            </Grid>\n        </Border>\n'''
s = s[:ns] + nav + s[ne:]

x.write_text(s, encoding='utf-8')

# Ensure model-aware art refreshes after startup and every camera selection.
p = Path('camera-auto-upload-windows/AndroidParity.cs')
a = p.read_text(encoding='utf-8')
needle = '            : "○ Manual editor — open Editor from the bottom bar, build the layout, then tap LOCK when you want incoming photos processed automatically.";'
if needle in a and 'RefreshCameraArtwork105(cp);' not in a:
    a = a.replace(needle, needle + '\n        RefreshCameraArtwork105(cp);', 1)
p.write_text(a, encoding='utf-8')
